        'foundation'=>[['01 / Experience','Familiar without becoming generic','Platform conventions support a product-specific hierarchy and task flow.',['Navigation','States','Components','Accessibility']],['02 / Platform','Capabilities used responsibly','Notifications, payments, biometrics and device features serve an identified user need.',['Swift','Device APIs','Privacy','Billing']],['03 / Release','Ownership beyond version one','Accounts, services, monitoring and update responsibilities are prepared for continued operation.',['Backend','App Store','Monitoring','Support']]],
        'integration_core'=>['bi-apple','iOS'],'integration_nodes'=>[['bi-person-lock','Identity'],['bi-credit-card','Billing'],['bi-bell','Push'],['bi-cloud','Backend']],
        'quality'=>[['bi-universal-access','Accessibility','Labels, focus, contrast and adaptable text support more users.'],['bi-shield-lock','Privacy','Collection, permissions and sensitive actions match documented responsibilities.'],['bi-lightning-charge','Responsiveness','Launch, navigation, lists and media remain fluid on supported devices.'],['bi-app-indicator','Release Quality','Signing, store information and production builds follow a repeatable path.']],
        'why_heading'=>'iOS Development With Clear Product and Release Ownership','why_paragraphs'=>['We bring user experience, connected-system planning and release work into one scope. Decisions are reviewed through flows, prototypes and working builds before they become production dependencies.', 'Our remote Gurugram team collaborates through planned reviews and written decisions. Client-owned accounts and visible release responsibilities make future updates easier to manage.'],
        'reasons'=>$sharedReasons,'cost_factors'=>$sharedCostFactors,'process'=>$sharedProcess,
        'faqs'=>[
            ['q'=>'How much does iOS app development cost in India?','a'=>'Cost depends on product scope, iPhone or iPad coverage, backend work, integrations, payments, device features and release requirements. We estimate after mapping the main journeys.'],
            ['q'=>'Do you build native iOS apps using Swift?','a'=>'Yes. Swift is recommended where native platform access, iOS-first investment or product requirements justify it.'],
            ['q'=>'Can one app be built for both iOS and Android?','a'=>'Yes, when React Native or Flutter suits the shared requirements. Platform-specific behaviour, testing and store releases are still handled separately.'],
            ['q'=>'Do you manage Apple App Store submission?','a'=>'Yes. We can support signing, build preparation, listing inputs, privacy details and review coordination using the client’s App Store Connect account.'],
            ['q'=>'Can you build iPad applications?','a'=>'Yes. We first confirm whether the use case requires an adaptive universal app or an iPad-focused workflow.'],
            ['q'=>'Can you integrate Apple Pay or subscriptions?','a'=>'Yes. Product eligibility, billing rules, server verification, renewals, cancellation and App Store requirements are reviewed before build.'],
            ['q'=>'How do you handle iOS app privacy?','a'=>'We identify data collection, permissions, third-party SDKs and account behaviour, then align interface consent, privacy information and technical controls.'],
            ['q'=>'Can you improve an existing iPhone app?','a'=>'Yes. We assess UX, crash and performance evidence, code, dependencies, backend constraints and store history before proposing changes.'],
            ['q'=>'How long does iOS app development take?','a'=>'A focused first release may take several weeks; integration-heavy or multi-role products take longer. Timing follows validated scope and prototype review.'],
            ['q'=>'Do you provide iOS maintenance after launch?','a'=>'Yes. Maintenance can cover compatibility updates, dependency changes, crash investigation, store releases and planned feature work.'],
        ],
        'cta_heading'=>'Planning an iPhone or iPad Product?','cta_text'=>'Tell us what users need to accomplish, which Apple devices matter and what the app must connect with. We will help define a responsible first release.',
    ],

    'custom-software-development' => [
        'name'=>'Custom Software Development','icon'=>'bi-window-stack','meta_title'=>'Custom Software Development Company | Chulbul Design','meta_desc'=>'Custom software development in India for business workflows, portals, automation and connected operations. Discovery, UX, engineering and support.','hero_badge'=>'Custom Software Development Company','hero_h1'=>'Custom Software Development That <span>Fits the Way You Work</span>','hero_desc'=>'We design and build business software around your roles, rules, data and integrations—when generic products create workarounds instead of solving the problem.','hero_img'=>'/assets/images/service-heroes/custom-software-development-hero.webp','hero_img_alt'=>'Custom software development architecture showing a business dashboard connected with workflows, APIs, database, cloud and secure user roles','browser_label'=>'your-workflow.app','chips'=>[['bi-diagram-3','Workflow mapped'],['bi-plug','Systems connected']],
        'intro_kicker'=>'Software shaped around a genuine operational need','intro_heading'=>'Custom Development Is Valuable When the Workflow Creates the Advantage','intro'=>['Off-the-shelf software is often the fastest answer to a standard requirement. Custom software becomes useful when teams depend on distinct approvals, calculations, data relationships, customer journeys or integrations that general products handle poorly.', 'We begin with the operating process rather than a list of requested screens. Users, decisions, exceptions and information ownership are documented before architecture. This reveals where configuration is enough, where integration can close a gap and where custom development is justified.', 'Chulbul Design builds portals, workflow systems, dashboards and business applications with visible scope and maintainable boundaries. The goal is not simply to automate an existing spreadsheet; it is to reduce friction without hiding a confusing process inside code.'],
        'cards_heading'=>'Custom Software Development Capabilities','cards_subtitle'=>'From workflow discovery to reliable production operation.','cards'=>[['bi-diagram-3','Workflow Software','Digital processes for approvals, hand-offs, exceptions and accountable status.'],['bi-person-workspace','Customer & Partner Portals','Secure self-service access to requests, files, transactions and communication.'],['bi-speedometer2','Operational Dashboards','Role-specific actions, summaries, filters and reports tied to business data.'],['bi-arrow-repeat','Business Automation','Rules and integrations that remove repeat manual work without hiding exceptions.'],['bi-plug','API Development','Documented interfaces connecting internal and third-party systems.'],['bi-database','Data & Migration','Structured models and controlled movement from legacy tools or spreadsheets.'],['bi-person-lock','Roles & Permissions','Access designed around responsibilities, sensitive actions and audit needs.'],['bi-cloud','Cloud Application Delivery','Deployable environments, configuration, backups and monitoring for web software.'],['bi-arrow-clockwise','Legacy Modernization','Staged improvement of ageing systems while protecting essential workflows and data.'],['bi-tools','Software Support','Defect resolution, monitoring, small improvements and planned product releases.']],
        'sections'=>[
            ['h2'=>'Turn Business Rules Into a Shared, Testable Product Scope','para'=>"Custom projects drift when the real process lives in conversations, spreadsheets and individual memory. Discovery identifies roles, triggers, decisions, exceptions and outputs in language business and technical stakeholders can review.\n\nWe separate must-have release behaviour from future opportunities. Acceptance criteria give each important workflow a clear definition of done.",'bullets'=>['User and stakeholder roles','Process rules and exception mapping','Data and document ownership','Prioritized first-release scope']],
            ['h2'=>'Integrate With Existing Systems Without Creating Hidden Fragility','para'=>"A new system may need to exchange data with CRM, ERP, finance, messaging, identity or industry platforms. We review available APIs, timing, limits and failure consequences before promising an integration.\n\nEach connection has an owner, expected behaviour and recovery path. Logs and audit information help teams understand what happened when systems disagree.",'bullets'=>['API and webhook review','Data mapping and validation','Retry and failure handling','Audit history and operational visibility']],
            ['h2'=>'Design Interfaces for the People Doing the Work','para'=>"Internal software should reduce cognitive load, not reproduce a database table on screen. Dashboards, forms and queues are designed around decisions and frequency of use.\n\nPrototypes expose unclear requirements early. Responsive behaviour and accessibility are included according to the devices and working environments in scope.",'bullets'=>['Role-specific navigation','Efficient forms and validation','Clear status and next actions','Responsive and accessible components']],
            ['h2'=>'Release in Manageable Stages With a Maintainable Foundation','para'=>"A phased release allows teams to validate process changes without placing every department and integration at risk on one date. Environments, migration rehearsal and rollback decisions are part of launch planning.\n\nDocumentation covers architecture, configuration, dependencies and operating responsibilities so the product can continue beyond the original project team.",'bullets'=>['Staged delivery and demonstrations','Migration and release rehearsal','Monitoring and backup ownership','Technical and operational handover']],
        ],
        'solutions_kicker'=>'Custom software for distinct responsibilities','solutions_heading'=>'Purpose-Built Systems for Customers, Teams and Operations','solutions_intro'=>'The right application reflects roles, decisions and data rather than forcing every department into the same interface.',
        'solutions'=>[['bi-person-workspace','Customer Portals','Accounts, requests, files, payments and service history in one secure journey.'],['bi-people','Partner Platforms','Onboarding, collaboration, documents and transactions across organizations.'],['bi-clipboard-data','Operations Systems','Queues, assignments, approvals and management visibility for daily work.'],['bi-box-seam','Inventory Tools','Stock, movement, reorder and exception workflows adapted to the operation.'],['bi-calendar-check','Scheduling Platforms','Availability, allocation, confirmations and administrative control.'],['bi-file-earmark-check','Compliance Workflows','Evidence, reviews, approvals and audit history for controlled processes.'],['bi-calculator','Quotation Systems','Configurable calculations, approval rules and document generation.'],['bi-wrench-adjustable','Field Service Software','Jobs, teams, assets, evidence and status for distributed work.'],['bi-bar-chart','Reporting Platforms','Role-based dashboards, filters, exports and decision-ready summaries.'],['bi-arrow-left-right','Integration Layers','Reliable exchange between systems with visible ownership and failure handling.']],
        'foundation'=>[['01 / Domain','Business meaning expressed clearly','Roles, rules, terms and exceptions form a shared model before implementation.',['Roles','Rules','Terms','Exceptions']],['02 / Product','Interfaces matched to decisions','Journeys and screens support what each user needs to understand and complete.',['Journeys','Prototype','States','Accessibility']],['03 / System','Boundaries teams can maintain','Services, data, integrations and operations have documented responsibilities.',['Architecture','Data','APIs','Operations']]],
        'integration_core'=>['bi-window-stack','Software'],'integration_nodes'=>[['bi-people','CRM'],['bi-building','ERP'],['bi-receipt','Finance'],['bi-chat-dots','Messaging']],
        'quality'=>[['bi-journal-code','Maintainability','Clear boundaries and documentation make change safer.'],['bi-shield-lock','Security','Access, validation and sensitive actions follow the product’s risk.'],['bi-arrow-clockwise','Reliability','Transactions and integrations include recovery and accountable states.'],['bi-activity','Observability','Logs and monitoring help teams understand production behaviour.']],
        'why_heading'=>'Custom Software With a Clear Build-versus-Buy Reason','why_paragraphs'=>['We evaluate configuration and integration before recommending custom code. Development is justified where ownership, workflow or user experience creates meaningful value.', 'Our remote process keeps requirements, demonstrations and decisions visible. For larger engineering needs, collaboration with SoftLes can add capacity while roles and accountability remain documented.'],
        'reasons'=>$sharedReasons,'cost_factors'=>$sharedCostFactors,'process'=>$sharedProcess,
        'faqs'=>[
            ['q'=>'What is custom software development?','a'=>'It is the design and development of a system around a specific organization’s users, workflows, rules, data and integrations rather than configuring a general product.'],
            ['q'=>'When should a business build custom software?','a'=>'Custom development is worth considering when a process creates strategic value, generic tools require costly workarounds, or integrations and ownership needs cannot be met responsibly through configuration.'],
            ['q'=>'How much does custom software development cost?','a'=>'Cost depends on modules, roles, data, integrations, migration, security, reporting and release scope. Discovery turns those factors into an estimate tied to deliverables.'],
            ['q'=>'Can you replace spreadsheets with custom software?','a'=>'Yes, but we first review why the sheets exist, who uses them and which exceptions they contain. The goal is to improve the process rather than copy spreadsheet complexity into a new screen.'],
            ['q'=>'Can custom software integrate with our CRM or ERP?','a'=>'Yes, where supported APIs or data exchange are available. Documentation, access, limits, ownership and recovery are confirmed during discovery.'],
            ['q'=>'Do you build customer and partner portals?','a'=>'Yes. Portals can include accounts, permissions, requests, documents, transactions, communication and administration tailored to the service journey.'],
            ['q'=>'Can you modernize existing legacy software?','a'=>'Yes. We assess code, architecture, data, integrations, usage and operational risk before recommending stabilization, staged replacement or a controlled rebuild.'],
            ['q'=>'Who owns the custom software source code?','a'=>'Ownership, repositories, accounts and third-party licences are stated in the proposal. Client-owned production access and a documented handover are recommended.'],
            ['q'=>'How do you prevent scope creep?','a'=>'We use documented requirements, release priorities, acceptance criteria and a visible change process. New ideas are evaluated without silently changing the committed scope.'],
            ['q'=>'Do you support custom software after launch?','a'=>'Yes. Support may include monitoring, defect resolution, infrastructure coordination, security updates and planned improvements.'],
        ],
        'cta_heading'=>'Does Generic Software Force Your Team Into Workarounds?','cta_text'=>'Show us the workflow, roles, current tools and recurring friction. We will help determine whether configuration, integration or custom development is the right next step.',
    ],

    'saas-development' => [
        'name'=>'SaaS Development','icon'=>'bi-cloud','meta_title'=>'SaaS Development Company India | Chulbul Design','meta_desc'=>'Custom SaaS development in India for multi-tenant products, subscription billing, onboarding, roles, analytics and scalable cloud operations.','hero_badge'=>'SaaS Development Company','hero_h1'=>'SaaS Development From <span>Focused MVP to Scalable Platform</span>','hero_desc'=>'We help founders and businesses shape, design and build subscription software with clear tenant boundaries, onboarding, billing, administration and product analytics.','hero_img'=>'/assets/images/service-heroes/saas-development-hero.webp','hero_img_alt'=>'SaaS development illustration showing a multi-tenant dashboard connected with onboarding, subscriptions, analytics, cloud scaling and integrations','browser_label'=>'your-saas.app','chips'=>[['bi-cloud','Tenant ready'],['bi-arrow-repeat','Subscription aware']],
        'intro_kicker'=>'Build the product and the operating model together','intro_heading'=>'A SaaS Product Is More Than a Web Application With a Pricing Page','intro'=>['Subscription software must help users reach value, manage access and understand what happens throughout the account lifecycle. The product also needs tools for support, billing, administration and reliable change across multiple customers.', 'We begin by defining the customer, problem, first value moment and boundaries of the MVP. Multi-tenancy, entitlements, billing and data isolation are architecture decisions, not features to bolt on after the interface is complete.', 'Chulbul Design connects product UX with engineering and operational planning. Founders receive reviewable flows, a prioritized release, clear technical responsibilities and a foundation that can evolve using evidence rather than an oversized launch backlog.'],
        'cards_heading'=>'SaaS Product Development Capabilities','cards_subtitle'=>'The customer experience and the platform operation planned as one system.','cards'=>[['bi-lightbulb','SaaS Discovery & MVP','Problem, customer, assumptions and smallest valuable release defined before build.'],['bi-building-lock','Multi-Tenant Architecture','Tenant boundaries, data isolation and administrative responsibilities planned deliberately.'],['bi-person-plus','Onboarding & Activation','Account setup, guidance and first-value journeys designed to reduce avoidable friction.'],['bi-credit-card','Subscription Billing','Plans, trials, upgrades, invoices and webhooks connected with product entitlements.'],['bi-person-gear','Roles & Permissions','Owners, members, administrators and support access mapped to responsibilities.'],['bi-speedometer2','SaaS Dashboards','Useful product data, actions and states organized around customer tasks.'],['bi-plug','API & Integrations','Documented connections with identity, payments, messaging and customer systems.'],['bi-bar-chart','Product Analytics','Events tied to activation, engagement, retention and operational questions.'],['bi-cloud-arrow-up','Cloud Deployment','Environments, configuration, monitoring, backups and release ownership.'],['bi-tools','SaaS Product Support','Defects, updates, infrastructure coordination and roadmap delivery after launch.']],
        'sections'=>[
            ['h2'=>'Define the Customer, Value Moment and MVP Boundary','para'=>"A SaaS MVP should test a business assumption, not simply contain fewer screens. We identify who pays, who uses the product and what successful early value looks like.\n\nJourneys and backlog priorities follow that definition. Features that do not support activation, core use or responsible operation remain visible for later rather than entering the first release by habit.",'bullets'=>['Ideal customer and user roles','Problem and value hypothesis','Activation and core-use journeys','Prioritized MVP and roadmap']],
            ['h2'=>'Design Multi-Tenancy, Entitlements and Billing as Core Architecture','para'=>"Tenant separation affects data, access, administration and support. Subscription state affects what customers can use and what the system should do when payment changes.\n\nWe map plans, trials, upgrades, cancellation, webhooks and account ownership before coding them. This reduces inconsistent access and support confusion later.",'bullets'=>['Tenant and account boundaries','Plan features and entitlements','Billing lifecycle and webhook handling','Support and administrator access']],
            ['h2'=>'Create Onboarding and Product Journeys That Lead to Value','para'=>"A new customer should understand what to do without reading a product manual. Onboarding collects only necessary information and guides the user toward a meaningful first outcome.\n\nEmpty states, examples and contextual help are designed around the learning curve. Product analytics measure important progress instead of recording every click without a question.",'bullets'=>['Focused account setup','Useful empty and first-use states','In-product guidance and recovery','Activation and engagement events']],
            ['h2'=>'Operate, Release and Improve a Live SaaS Platform','para'=>"A subscription product changes continuously. Staging, migrations, feature rollout, monitoring and customer support need repeatable practices before growth makes them urgent.\n\nWe document environments and ownership, test critical account and billing journeys and plan post-launch work from real product evidence.",'bullets'=>['Staging and release workflow','Database migration discipline','Monitoring and support visibility','Evidence-led product roadmap']],
        ],
        'solutions_kicker'=>'SaaS products for different markets and workflows','solutions_heading'=>'Subscription Platforms Built Around a Clear Customer Job','solutions_intro'=>'Each model has different account, billing, data and support responsibilities.','solutions'=>[['bi-briefcase','B2B SaaS','Company accounts, teams, permissions and longer onboarding journeys.'],['bi-person','Self-Serve SaaS','Fast sign-up, guided activation, billing and in-product support.'],['bi-diagram-3','Workflow SaaS','Queues, approvals and collaboration around repeat business processes.'],['bi-bar-chart','Analytics SaaS','Data connection, dashboards, reports and controlled sharing.'],['bi-calendar-check','Scheduling SaaS','Availability, resources, bookings, reminders and subscriptions.'],['bi-people','HR & Team Products','Employee records, requests, approvals and role-aware workflows.'],['bi-mortarboard','Education SaaS','Organizations, instructors, learners, content and progress.'],['bi-heart-pulse','Health Operations SaaS','Controlled scheduling and operational journeys within defined compliance scope.'],['bi-shop','Vertical SaaS','Purpose-built workflows for a specific industry and customer vocabulary.'],['bi-plug','API-First Products','Documented product capabilities delivered to other software through APIs.']],
        'foundation'=>[['01 / Market','A specific customer and problem','Positioning, user roles and value define the release rather than a generic feature list.',['Customer','Problem','Value','MVP']],['02 / Product','Activation and continued use','Onboarding, core journeys and account states help customers reach and repeat value.',['Onboarding','Core UX','Billing','Analytics']],['03 / Platform','Safe operation across tenants','Architecture, support, deployment and monitoring handle a growing customer base.',['Tenancy','Security','Release','Support']]],
        'integration_core'=>['bi-cloud','SaaS'],'integration_nodes'=>[['bi-person-lock','Identity'],['bi-credit-card','Billing'],['bi-envelope','Messaging'],['bi-bar-chart','Analytics']],
        'quality'=>[['bi-building-lock','Isolation','Tenant data and access boundaries are explicit and testable.'],['bi-arrow-repeat','Lifecycle','Trials, upgrades, cancellation and account states remain consistent.'],['bi-speedometer2','Scalability','Architecture and monitoring address realistic growth paths.'],['bi-journal-code','Operability','Support, deployment and change responsibilities are documented.']],
        'why_heading'=>'SaaS Delivery That Connects Product Decisions With Engineering','why_paragraphs'=>['We challenge oversized MVPs and surface the operational work behind subscriptions, tenants and support. This keeps the first release focused without pretending future complexity does not exist.', 'Our Gurugram team collaborates remotely through prototypes, working increments and written decisions. Product and technical trade-offs stay visible to founders and stakeholders.'],
        'reasons'=>$sharedReasons,'cost_factors'=>$sharedCostFactors,'process'=>$sharedProcess,
        'faqs'=>[
            ['q'=>'What is included in SaaS development?','a'=>'Scope may include discovery, UX, multi-tenant architecture, onboarding, roles, billing, dashboards, APIs, analytics, cloud deployment and support tools.'],
            ['q'=>'How much does SaaS development cost in India?','a'=>'Cost depends on MVP scope, tenants, roles, billing, integrations, data, administration, security and infrastructure. We estimate after mapping the customer and operational journeys.'],
            ['q'=>'How do you define a SaaS MVP?','a'=>'An MVP is the smallest dependable product that can test a clear customer value assumption. It still includes the access, support and operational work required to serve real users.'],
            ['q'=>'Can you build multi-tenant SaaS architecture?','a'=>'Yes. We define tenant boundaries, data isolation, account administration and access patterns according to the product’s risk and expected scale.'],
            ['q'=>'Can you integrate Stripe or Razorpay subscriptions?','a'=>'Yes. We map plans, trials, recurring billing, webhooks, entitlements, upgrades, cancellation and failure states before implementation.'],
            ['q'=>'Do you build SaaS dashboards and admin panels?','a'=>'Yes. Customer dashboards and internal administration are designed around their separate roles, decisions and data access.'],
            ['q'=>'Can you help with SaaS product strategy?','a'=>'We help clarify users, core problem, value moment, release priorities and product journeys. Market validation remains a shared business responsibility.'],
            ['q'=>'How is SaaS security handled?','a'=>'Security review includes tenancy, authentication, permissions, validation, sensitive operations, dependencies, infrastructure and monitoring according to scope.'],
            ['q'=>'Can an existing SaaS product be redesigned or scaled?','a'=>'Yes. We assess product journeys, architecture, data, performance, support evidence and release risk before recommending a staged plan.'],
            ['q'=>'Do you provide post-launch SaaS support?','a'=>'Yes. Support can include monitoring, defect resolution, infrastructure coordination, dependency updates and planned roadmap releases.'],
        ],
        'cta_heading'=>'Turning a SaaS Idea Into a Focused Product?','cta_text'=>'Share the target customer, problem, current evidence and first-release assumptions. We will help shape a practical product and engineering plan.',
    ],

    'crm-development' => [
        'name'=>'CRM Development','icon'=>'bi-people','meta_title'=>'Custom CRM Development Company | Chulbul Design','meta_desc'=>'Custom CRM development in India for lead capture, sales pipelines, follow-ups, quotations, communication, automation and actionable reporting.','hero_badge'=>'Custom CRM Development Company','hero_h1'=>'Custom CRM Development for <span>Clearer Sales Operations</span>','hero_desc'=>'We build CRM software around your lead sources, stages, responsibilities and follow-up process—so the system supports the team instead of creating more administration.','hero_img'=>'/assets/images/service-heroes/crm-development-hero.webp','hero_img_alt'=>'Custom CRM development illustration showing a lead pipeline connected with customer profiles, follow-ups, communication, automation and sales analytics','browser_label'=>'your-sales.crm','chips'=>[['bi-funnel','Pipeline clear'],['bi-bell','Follow-ups visible']],
        'intro_kicker'=>'A CRM should support sales behaviour, not just store contacts','intro_heading'=>'The Best CRM Structure Starts With How a Lead Becomes a Customer','intro'=>['Many CRM implementations fail because the software contains fields and dashboards without reflecting the decisions salespeople make each day. Teams then return to spreadsheets, personal reminders and chat messages while the CRM becomes an incomplete reporting tool.', 'We map lead sources, qualification, ownership, stages, follow-ups, quotations and hand-offs before designing the system. The aim is to make the next action visible, reduce duplicate entry and give managers trustworthy context.', 'A custom CRM is appropriate when the sales process or integrations create a genuine requirement that standard products cannot meet economically. We also identify where configuring an existing CRM would be the better choice.'],
        'cards_heading'=>'Custom CRM Development Capabilities','cards_subtitle'=>'Sales, customer and management workflows connected in one accountable system.','cards'=>[['bi-inbox','Lead Capture','Website, campaign, import and manual leads entering with source context.'],['bi-funnel','Pipeline Management','Stages, ownership, probability and next actions aligned with the sales process.'],['bi-calendar2-check','Tasks & Follow-Ups','Reminders, activities and overdue visibility connected to each opportunity.'],['bi-chat-dots','Communication Integration','Email, calling or supported messaging activity linked with customer context.'],['bi-file-earmark-text','Quotation Workflows','Products, pricing, approvals and proposal documents generated consistently.'],['bi-arrow-left-right','Assignment & Routing','Rules for territory, service, availability or team-based lead ownership.'],['bi-gear','Sales Automation','Useful triggers and alerts that reduce repeat work without hiding decisions.'],['bi-bar-chart','CRM Reporting','Source, stage, activity and outcome views built from accountable data.'],['bi-phone','Mobile CRM Access','Responsive or app-based workflows for field and travelling teams.'],['bi-plug','CRM Integrations','Connections with websites, marketing, finance and service systems.']],
        'sections'=>[
            ['h2'=>'Map the Sales Process Before Designing the Dashboard','para'=>"A CRM should represent the real path from enquiry to outcome, including qualification, pauses, rejection and hand-off. We interview the people doing the work and compare management reporting needs with the information the team can realistically maintain.\n\nFields, stages and required actions are then limited to what has a clear purpose. This improves adoption and data quality more than adding another chart.",'bullets'=>['Lead sources and qualification rules','Pipeline stages and ownership','Activities, follow-ups and hand-offs','Required data and reporting questions']],
            ['h2'=>'Connect Lead Capture, Communication and Commercial Documents','para'=>"A sales team loses context when website enquiries, calls, messages, quotations and invoices live in unrelated tools. Supported integrations can bring key events into one customer timeline without copying every piece of data everywhere.\n\nWe define the source of truth, permissions and failure behaviour for each connection. Automation remains visible and reversible where business consequences matter.",'bullets'=>['Website and campaign lead capture','Email or supported messaging integration','Quotation and approval workflows','Finance or service hand-off integration']],
            ['h2'=>'Design CRM Screens Around the Next Useful Action','para'=>"Salespeople need quick context: who the customer is, what happened, what is due and what can move the opportunity forward. Record pages and lists prioritize those decisions over decorative reporting.\n\nManagers receive views of pipeline health, inactivity and outcomes while access remains appropriate to team structure and customer sensitivity.",'bullets'=>['Role-specific dashboards','Fast search, filters and saved views','Clear activity timeline','Mobile-friendly lead actions']],
            ['h2'=>'Migrate and Launch Without Losing Sales Continuity','para'=>"Existing contacts and opportunities often contain duplicates, inconsistent stages and missing ownership. Migration starts with mapping and cleanup rules rather than importing every historic problem.\n\nPilot users validate the process before broader rollout. Training, permissions, monitoring and support routes are prepared so adoption continues after launch.",'bullets'=>['Data mapping and duplicate strategy','Pilot migration and validation','Role and permission review','Training, launch and support plan']],
        ],
        'solutions_kicker'=>'CRM systems for different sales motions','solutions_heading'=>'Customer Management Shaped Around the Way Your Team Sells','solutions_intro'=>'A field-sales team, service business and B2B account team need different information and controls.','solutions'=>[['bi-briefcase','B2B Sales CRM','Accounts, contacts, opportunities and longer decision journeys.'],['bi-house','Real Estate CRM','Property enquiries, agents, visits, follow-ups and source tracking.'],['bi-tools','Home Services CRM','Service enquiries, areas, quotations, scheduling and repeat work.'],['bi-mortarboard','Education Admissions','Student enquiries, counsellors, stages, appointments and enrolment outcomes.'],['bi-heart-pulse','Clinic Enquiry CRM','Consent-aware leads, appointments and service follow-up within scope.'],['bi-truck','Distribution Sales','Dealers, territories, visits, quotations and order hand-offs.'],['bi-megaphone','Marketing Lead CRM','Campaign sources, qualification, nurture and accountable conversion.'],['bi-headset','Service CRM','Customer issues, assignments, status, history and escalation.'],['bi-phone','Field Sales CRM','Mobile activities, location-aware work and manager visibility.'],['bi-diagram-3','Multi-Team CRM','Controlled hand-offs across sales, operations, finance and support.']],
        'foundation'=>[['01 / Process','A shared definition of the pipeline','Sources, stages, ownership and outcomes mean the same thing across teams.',['Sources','Stages','Owners','Outcomes']],['02 / Adoption','Useful in everyday sales work','Fast records, follow-ups and communication context support the next action.',['Tasks','Timeline','Mobile','Search']],['03 / Insight','Reports based on accountable data','Dashboards answer management questions using fields the team can maintain.',['Quality','Pipeline','Activity','Conversion']]],
        'integration_core'=>['bi-people','CRM'],'integration_nodes'=>[['bi-globe','Website'],['bi-chat-dots','Messages'],['bi-file-text','Quotes'],['bi-receipt','Finance']],
        'quality'=>[['bi-person-check','Adoption','The interface reduces unnecessary entry and supports daily actions.'],['bi-shield-lock','Access','Customer and commercial information follows role responsibilities.'],['bi-check2-square','Data Quality','Required fields, duplicates and ownership are governed deliberately.'],['bi-bar-chart','Useful Reporting','Metrics connect to clear sales and management questions.']],
        'why_heading'=>'CRM Development Grounded in the Sales Process','why_paragraphs'=>['We do not assume custom CRM is always the answer. Discovery compares the cost of configuring an established product with the value and ownership of a purpose-built system.', 'When custom development is justified, sales users and managers review the process and prototypes together. That helps the delivered CRM support adoption as well as reporting.'],
